CREATE SCHEMA IF NOT EXISTS content;
CREATE TABLE content.faq_category(id text PRIMARY KEY,label text NOT NULL,sort_order integer NOT NULL DEFAULT 0,published boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1);
CREATE TABLE content.faq_item(id text PRIMARY KEY,category text NOT NULL REFERENCES content.faq_category(id),question text NOT NULL,answer text NOT NULL,keywords text NOT NULL DEFAULT '',sort_order integer NOT NULL DEFAULT 0,published boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1);
CREATE TABLE content.faq_change(id bigserial PRIMARY KEY,actor_id text NOT NULL,entity_id text NOT NULL,action text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
